{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Direct biodistribution in mice showed [18F]FMC brain uptake of 5.47% ID/g at 2 min and was explicitly labeled as good BBB penetration; this high-transfer analogue supports meaningful CNS access for the query chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Ex vivo biodistribution in normal ICR mice showed the closely related radiotracer (R)-[18F]5 crossed the BBB with brain uptake of 7.06% ID/g at 2 min, providing direct evidence of CNS penetration for a similar heteroaromatic aniline-like scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Biodistribution studies in mice showed [18F]FPYBF-2 high brain uptake of 7.38% ID/g at 2 min, confirming that this class of heteroaromatic compounds can achieve rapid and meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "In rats, [18F]GE-067 (flutemetamol) showed rapid brain uptake of 3.67% ID/g at 5 min, demonstrating that related fluorophenyl/heteroaryl structures are capable of robust BBB penetration in vivo.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate direct BBB penetration and meaningful brain uptake in rodents or humans, and the query shares the relevant small heteroaromatic, methylamino, and fluoroaryl features. Therefore the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct CSF or unbound brain concentration data are available for the exact query molecule.",
    "Efflux-transporter status was not directly measured for the query, though multiple close analogues show net brain uptake despite similar scaffolds."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

